// Retriever interface abstracts both sparse and dense engines
interface Retriever {
    List<DocumentScore> retrieve(String query, int topN);
}

// DocumentScore holds id, raw score, and source type
class DocumentScore {
    final String docId;
    final double score;
    final Source source; // enum { SPARSE, DENSE }
}

// FusionStrategy defines how two score lists are merged
interface FusionStrategy {
    List<DocumentScore> fuse(List<DocumentScore> sparse, List<DocumentScore> dense);
}

// Concrete strategies
class WeightedSumFusion implements FusionStrategy {
    private final double alpha; // BM25 weight
    private final double beta;  // Dense weight
    public List<DocumentScore> fuse(...) { /* implementation */ }
}

class RRFusion implements FusionStrategy {
    public List<DocumentScore> fuse(...) { /* implementation */ }
}

// ReRanker uses a lightweight neural model (e.g., TensorFlow Lite)
class ReRanker {
    public double rank(String query, String docId) { /* forward pass */ }
}
