```python
from langchain.graphs import StateGraph, State
def retrieve(state: State): 
    kw = keyword_service(state["query"])
    vec = vector_service(state["embedding"])
    return {"kw": kw, "vec": vec}
def fuse(state: State):
    fused = fusion_engine(state["kw"], state["vec"])
    return {"context": fused}
def generate(state: State):
    answer = llm.invoke(state["query"], context=state["context"])
    return {"answer": answer}
graph = StateGraph()
graph.add_node("retrieve", retrieve)
graph.add_node("fuse", fuse)
graph.add_node("generate", generate)
graph.add_edge("retrieve", "fuse")
graph.add_edge("fuse", "generate")
workflow = graph.compile()
result = workflow.invoke({"query": "How does hybrid retrieval work?"})
print(result["answer"])
```
